            float[] xs = {-k * 2.4f, 0f, k * 2.4f};
            for (int i = 0; i < 3; i++) {
                float x = xs[i];
                if (i == 1) { c.drawLine(x - k, -k, x - k, k, p); c.drawLine(x - k, -k, x + k, k, p); c.drawLine(x + k, -k, x + k, k, p); }
                else { c.drawLine(x - k, -k, x + k, -k, p); c.drawLine(x, -k, x, k, p); }
            }
        }

        private void drawTurret(Draw2D c, Prop q) {
            RB base_ = q.bodies.get(0), gun = q.barrel;
            int col = tint(q, q.color, q.flash);
            foreach (Shape s in base_.shapes) { if (s.type == Shape.CAPSULE) capsuleShape(c, s, s.color); else boxShape(c, s, s.color, true); }
            if (gun != null) {
                Shape bar = gun.shapes.get(0), head = gun.shapes.get(1);
                if (q.target != null && !q.dead && q.on) {
                    p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(1.6f); p.setColor(unchecked((int)0x88ff2a2aU));
                    c.emissive(true);
                    float mx = gun.x + (float) Math.cos(gun.a) * 28f, my = gun.y + (float) Math.sin(gun.a) * 28f;
                    c.drawLine(mx, my, mx + (float) Math.cos(gun.a) * 900f, my + (float) Math.sin(gun.a) * 900f, p);
                    c.emissive(false);
                }
                capsuleShape(c, bar, bar.color);
                boxShape(c, head, col, true);
                p.setStyle(Paint.Style.FILL);
                p.setColor(unchecked((int)0xFF1b222bU));
                c.drawCircle(head.cx, head.cy, 5.5f, p);
                int eye = q.dead ? unchecked((int)0xFF3b4652U) : (!q.on ? unchecked((int)0xFF555b66U) : (q.target != null ? unchecked((int)0xFFff3b30U) : unchecked((int)0xFF35e0ffU)));
                p.setColor(eye);
                c.emissive(!q.dead && q.on);
                c.drawCircle(head.cx, head.cy, 3f, p);
                c.emissive(false);
            }
        }

        private void drawDrone(Draw2D c, Prop q) {
            RB m = q.main();
            Shape s = m.shapes.get(0);
            capsuleShape(c, s, tint(q, q.color, q.flash));
            bool on = q.on && !q.dead;
            float spin = on ? (float) Math.abs(Math.sin(time * 50f)) : 1f;
            float ux = s.ax, uy = s.ay, nx = uy, ny = -ux;
            if (ny > 0) { nx = -nx; ny = -ny; }
            for (int k = -1; k <= 1; k += 2) {
                float rx = s.cx + ux * s.hl * k, ry = s.cy + uy * s.hl * k;
                float hx = rx + nx * 9f, hy = ry + ny * 9f;
                p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(3f); p.setColor(unchecked((int)0xFF2a2e35U));
                c.drawLine(rx, ry, hx, hy, p);
                p.setStrokeWidth(3.2f); p.setColor(on ? unchecked((int)0x88c8d0daU) : unchecked((int)0xFF8a929cU));
                float half = 6f + 14f * spin;
                c.drawLine(hx - ux * half, hy - uy * half, hx + ux * half, hy + uy * half, p);
            }
            p.setStyle(Paint.Style.FILL);
            p.setColor(unchecked((int)0xFF111418U)); c.drawCircle(s.cx - nx * 5f, s.cy - ny * 5f, 4.6f, p);
            p.setColor(q.dead ? unchecked((int)0xFF3b4652U) : (!q.on ? unchecked((int)0xFF555b66U) : (q.target != null ? unchecked((int)0xFFff3b30U) : unchecked((int)0xFF6dff8aU))));
            c.emissive(on);
            c.drawCircle(s.cx - nx * 5f, s.cy - ny * 5f, 2.6f, p);
            c.emissive(false);
        }

