        /** Cracks (wood, brick, blocks) or dents and scratches (metal) where things were hit. */
        private void cracks(Draw2D c, Prop q) {
            RB m = q.main();
            bool metal = q.type == Items.BARREL || q.type == Items.XBARREL || q.type == Items.STEEL || q.type == Items.FRIDGE || q.color == Build.STEEL;
            local(c, m.x, m.y, m.a);
            float hw = q.hw, hh = q.hh;
            p.setStrokeCap(Paint.Cap.ROUND);
            for (int i = 0; i < q.ncr; i++) {
                float u = q.crU[i], v = q.crV[i], k = Math.min(1.4f, q.crS[i]);
                int seed = (int) (u * 13f + v * 7f) * 31 + i * 977 + q.id * 7919;
                if (q.crS[i] >= 2f) {                       // a bullet hole: dark pit, chipped rim, a few short cracks
                    p.setStyle(Paint.Style.FILL);
                    p.setColor(alpha(unchecked((int)0xFF000000U), 0.35f)); c.drawCircle(u, v, 4.2f, p);
                    p.setColor(unchecked((int)0xFF0d0b09U)); c.drawCircle(u, v, 2.4f, p);
                    p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(1f); p.setColor(alpha(metal ? unchecked((int)0xFFdfe4eaU) : unchecked((int)0xFFe8d8c8U), 0.5f));
                    for (int sct = 0; sct < 4; sct++) {
                        int shs = sct * 3;
                        float an = (((Sys.ushr(seed, shs)) & 63) / 63f + sct) * 1.57f;
                        c.drawLine(u + (float) Math.cos(an) * 2.6f, v + (float) Math.sin(an) * 2.6f, u + (float) Math.cos(an) * 6.5f, v + (float) Math.sin(an) * 6.5f, p);
                    }
                    continue;
                }
                if (metal) {
                    float r = 3f + k * 7f;
                    p.setStyle(Paint.Style.FILL);
                    p.setColor(alpha(unchecked((int)0xFF000000U), 0.22f + 0.2f * Math.min(1f, k)));
                    rf.set(u - r, v - r * 0.75f, u + r, v + r * 0.75f); c.drawOval(rf, p);
                    p.setColor(alpha(unchecked((int)0xFFffffffU), 0.22f));
                    rf.set(u - r * 0.8f, v - r * 0.7f, u + r * 0.2f, v - r * 0.2f); c.drawOval(rf, p);
                    p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(1f); p.setColor(alpha(unchecked((int)0xFFdfe4eaU), 0.55f));
                    for (int sct = 0; sct < 2; sct++) {
                        int sh = sct * 5;
                        float an = ((Sys.ushr(seed, sh)) & 63) / 63f * 3.1f;
                        float l = r * (1.2f + k);
                        c.drawLine(u, v, u + (float) Math.cos(an) * l, v + (float) Math.sin(an) * l * 0.6f, p);
                    }
                    continue;
                }
                // a jagged star of cracks: a few branches, each one bending twice
                int branches = 3 + (int) (k * 3f);
                float len = (6f + k * 22f) * Math.min(1f, Math.max(0.5f, Math.min(hw, hh) / 25f) + 0.3f);
                p.setStyle(Paint.Style.STROKE);
                for (int b = 0; b < branches; b++) {
                    int h = seed * (b + 5) * 1103515245 + 12345 * (b + 1);
                    float an = b * 6.283f / branches + (((Sys.ushr(h, 8)) & 255) / 255f - 0.5f) * 1.1f;
                    float x0 = u, y0 = v;
                    float seg = len * (0.35f + ((Sys.ushr(h, 16)) & 127) / 127f * 0.35f);
                    for (int st = 0; st < 3; st++) {
                        int sh = st * 4 + 2;
                        float bend = (((Sys.ushr(h, sh)) & 15) / 15f - 0.5f) * 0.9f;
                        float x1 = x0 + (float) Math.cos(an + bend) * seg, y1 = y0 + (float) Math.sin(an + bend) * seg;
                        x1 = Math.max(-hw, Math.min(hw, x1)); y1 = Math.max(-hh, Math.min(hh, y1));
                        p.setStrokeWidth(Math.max(0.8f, (2.4f - st * 0.7f) * (0.6f + k * 0.4f)));
                        p.setColor(q.color == Build.GLASS ? alpha(unchecked((int)0xFFffffffU), 0.9f) : alpha(unchecked((int)0xFF15100cU), 0.8f));
                        c.drawLine(x0, y0, x1, y1, p);
