            if (q.wear > 0.05f) { p.setColor(alpha(unchecked((int)0xFF6e0a10U), 0.5f * q.wear)); c.drawCircle(-6f, -10f * k - 3f, 6f, p); c.drawCircle(7f, -14f * k - 2f, 4f, p); }
