        // ---------------------------------------------------------------------------------- people -----

        private int bodyColor(Person b, int col) {
            if (b.frozenT > 0f) return tint(b, mix(col, unchecked((int)0xFFbfe6ffU), 0.62f), b.flash);
            if (b.dead) col = mix(col, unchecked((int)0xFF9aa0a8U), 0.22f);
            if (b.fleshy() && b.kind != Person.RUSTMAN) {
                // gore V6: losing blood drains the colour from the skin; the dead go grey-blue as the minutes pass
                if (!b.dead && b.maxBlood > 0f) { float bl = b.blood / b.maxBlood; if (bl < 0.65f) col = mix(col, unchecked((int)0xFFd9cfc6U), (0.65f - bl) / 0.65f * 0.5f); }
                else if (b.dead) col = mix(col, unchecked((int)0xFF7f8b9cU), Math.min(0.45f, b.deadT / 90f * 0.45f));
            }
            if (b.rustT >= 0f) col = mix(col, unchecked((int)0xFFb5651dU), Math.max(0f, Math.min(0.85f, (1f - b.rustT / 7f) * 0.85f)));
            return tint(b, col, b.flash);
        }

        /** Colour of a hurt part: flesh reddens and darkens, metal blackens. */
        private int hurtColor(Person b, int idx, int col) {
            float dmg = 1f - b.hp[idx] / Person.maxHp(b, idx);
            if (dmg > 0.05f) {
                float k = Math.min(1f, dmg) * 0.42f;
                int to = b.kind == Person.ROBOT ? unchecked((int)0xFF22252aU) : (b.kind == Person.ZOMBIE ? unchecked((int)0xFF3e5a22U) : (b.kind == Person.SKELETON ? unchecked((int)0xFF8a8268U) : unchecked((int)0xFF6e1f22U)));
                col = mix(col, to, k);
            }
            return bodyColor(b, col);
        }

        /** A limb in the sandbox style: dark outline, flat fill, a lit edge on top and a shaded one below. */
        private void limb(Draw2D c, Shape s, int col) {
            float x0 = s.cx - s.ax * s.hl, y0 = s.cy - s.ay * s.hl, x1 = s.cx + s.ax * s.hl, y1 = s.cy + s.ay * s.hl;
            p.setStyle(Paint.Style.STROKE);
            p.setColor(dark(col, 0.62f));
            p.setStrokeWidth(s.r * 2f + 2.6f);
            c.drawLine(x0, y0, x1, y1, p);
            p.setColor(col);
            p.setStrokeWidth(s.r * 2f);
            c.drawLine(x0, y0, x1, y1, p);
            if (!detail) return;
            float nx = -s.ay, ny = s.ax;
            if (ny > 0f) { nx = -nx; ny = -ny; }          // n points up
            float o = s.r * 0.42f;
            p.setStrokeWidth(s.r * 0.5f);
            p.setColor(light(col, 0.16f));
            c.drawLine(x0 + nx * o, y0 + ny * o, x1 + nx * o, y1 + ny * o, p);
            p.setColor(dark(col, 0.16f));
            c.drawLine(x0 - nx * o, y0 - ny * o, x1 - nx * o, y1 - ny * o, p);
        }

        // ---------------------------------------------------------------- outfits V2 (humans) ---

        public const int TOP_TEE = 0, TOP_STRIPES = 1, TOP_HOODIE = 2, TOP_SHIRT = 3, TOP_PLAID = 4, TOP_JACKET = 5, TOP_PRINT = 6;
        public const int BOT_JEANS = 0, BOT_CHINOS = 1, BOT_CARGO = 2, BOT_SHORTS = 3;
        public static readonly int[] SHOE = {unchecked((int)0xFF2b2b30U), unchecked((int)0xFFe9e9ecU), unchecked((int)0xFF5a3a24U), unchecked((int)0xFF2f4f7aU)};

        /** A stable hash of the person's colours: the outfit survives saving and loading. */
        public static int outfit(Person b) {
            int h = b.shirt * 31 + b.pants * 17 + b.hair * 7 + b.skin;
            h ^= (Sys.ushr(h, 13));
            h *= 0x5bd1e995;
            h ^= (Sys.ushr(h, 15));
            return h & 0x7fffffff;
        }
        public static int topStyle(Person b) { return b.kind == Person.HUMAN ? (outfit(b) >> 3) % 7 : -1; }
        public static int bottomStyle(Person b) { return b.kind == Person.HUMAN ? (outfit(b) >> 7) % 4 : -1; }
        public static int hairStyle(Person b) { return b.kind == Person.HUMAN ? (outfit(b) >> 11) % 6 : 0; }
        public static int shoeColor(Person b) { return b.kind == Person.HUMAN ? SHOE[(outfit(b) >> 15) % SHOE.Length] : unchecked((int)0xFF2b2b30U); }
        public static bool beard(Person b) { return b.kind == Person.HUMAN && ((outfit(b) >> 18) & 7) == 0 && b.scale > 0.8f; }

        private bool flesh(Person b) { return b.fleshy(); }

        private void part(Draw2D c, Person b, int idx, int col) {
            if (b.gibbed[idx]) return;
            Shape s = b.rb[idx].shapes.get(0);
            bool shaped = (idx == Person.CHEST || idx == Person.PELVIS) && humanoid(b) && detail;
            if (s.type == Shape.CAPSULE) { if (!shaped) limb(c, s, hurtColor(b, idx, col)); }
            else if (s.type == Shape.CIRCLE) circleShape(c, s, hurtColor(b, idx, col));
            if (detail) { soaked(c, b, idx, s); torn(c, b, idx, s); rustPatches(c, b, idx, s); }
            wounds(c, b, idx);
        }

        /** Blood V3: clothes and skin soak up blood in dark blotches. */
        private void soaked(Draw2D c, Person b, int idx, Shape s) {
            float k = b.soak[idx];
            if (k < 0.04f || !gore || s.type != Shape.CAPSULE || b.frozenT > 0f) return;
            int col = b.kind == Person.ZOMBIE ? unchecked((int)0xFF2f5a14U) : unchecked((int)0xFF5e0710U);
            p.setStyle(Paint.Style.FILL);
            p.setColor(alpha(col, 0.3f + 0.45f * Math.min(1f, k)));
            int n = 1 + (int) (Math.min(1f, k) * 3f);
            for (int i = 0; i < n; i++) {
                int h = (b.id * 131 + idx * 37 + i * 71) * 2654435;
                float t = ((Sys.ushr(h, 8)) & 255) / 255f * 1.6f - 0.8f;
                float off = ((Sys.ushr(h, 17)) & 255) / 255f - 0.5f;
                float r = s.r * (0.5f + 0.45f * Math.min(1f, k)) * (0.75f + ((Sys.ushr(h, 4)) & 7) / 28f);
                float x = s.cx + s.ax * s.hl * t - s.ay * off * s.r * 0.5f, y = s.cy + s.ay * s.hl * t + s.ax * off * s.r * 0.5f;
                c.drawCircle(x, y, Math.min(r, s.r * 0.95f), p);
            }
        }

        /** Gore V4: a limb wrecked far beyond broken shows torn muscle and the bone inside. */
        private void torn(Draw2D c, Person b, int idx, Shape s) {
            if (!gore || s.type != Shape.CAPSULE || !flesh(b) || b.frozenT > 0f) return;
            float dmg = -b.hp[idx] / Person.maxHp(b, idx);
            if (dmg < 0.2f) return;
            float k = Math.min(1f, (dmg - 0.2f) * 1.8f);
            bool z = b.kind == Person.ZOMBIE;
            float t0 = -0.15f - 0.55f * k, t1 = 0.2f + 0.5f * k;
            float x0 = s.cx + s.ax * s.hl * t0, y0 = s.cy + s.ay * s.hl * t0, x1 = s.cx + s.ax * s.hl * t1, y1 = s.cy + s.ay * s.hl * t1;
            float nx = -s.ay * s.r, ny = s.ax * s.r;
            p.setStyle(Paint.Style.STROKE);
            p.setColor(z ? unchecked((int)0xFF3f6420U) : unchecked((int)0xFF6e0f18U)); p.setStrokeWidth(s.r * 1.55f); c.drawLine(x0, y0, x1, y1, p);
            p.setColor(z ? unchecked((int)0xFF5f8a32U) : unchecked((int)0xFFa52531U)); p.setStrokeWidth(s.r * 1.15f); c.drawLine(x0, y0, x1, y1, p);
            // fibres of the muscle
            p.setStrokeWidth(Math.max(0.7f, s.r * 0.12f)); p.setColor(alpha(z ? unchecked((int)0xFF2a4210U) : unchecked((int)0xFF3f050aU), 0.7f));
            for (int i = -1; i <= 1; i++) c.drawLine(x0 + nx * i * 0.35f, y0 + ny * i * 0.35f, x1 + nx * i * 0.35f, y1 + ny * i * 0.35f, p);
            p.setColor(alpha(unchecked((int)0xFFffffffU), 0.22f)); p.setStrokeWidth(Math.max(0.8f, s.r * 0.18f));
            c.drawLine(x0 - nx * 0.5f, y0 - ny * 0.5f, x1 - nx * 0.5f, y1 - ny * 0.5f, p);
            if (k > 0.3f) {
                // the bone, with knobbly ends, cracked through when the part is broken
                float bx0 = x0 + (x1 - x0) * 0.12f, by0 = y0 + (y1 - y0) * 0.12f, bx1 = x1 - (x1 - x0) * 0.08f, by1 = y1 - (y1 - y0) * 0.08f;
                p.setColor(unchecked((int)0xFF9d9682U)); p.setStrokeWidth(s.r * 0.62f); c.drawLine(bx0, by0, bx1, by1, p);
                p.setColor(unchecked((int)0xFFefe9d6U)); p.setStrokeWidth(s.r * 0.45f); c.drawLine(bx0, by0, bx1, by1, p);
                p.setStyle(Paint.Style.FILL); p.setColor(unchecked((int)0xFFefe9d6U));
                c.drawCircle(bx1 + nx * 0.18f, by1 + ny * 0.18f, s.r * 0.3f, p); c.drawCircle(bx1 - nx * 0.18f, by1 - ny * 0.18f, s.r * 0.3f, p);
                if (b.broken[idx]) {
                    float mx = (bx0 + bx1) * 0.5f, my = (by0 + by1) * 0.5f;
                    p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(Math.max(1f, s.r * 0.14f)); p.setColor(unchecked((int)0xFF4a0a0eU));
                    c.drawLine(mx - nx * 0.3f, my - ny * 0.3f, mx + nx * 0.1f + s.ax * 3f, my + ny * 0.1f + s.ay * 3f, p);
                    c.drawLine(mx + nx * 0.1f + s.ax * 3f, my + ny * 0.1f + s.ay * 3f, mx + nx * 0.3f, my + ny * 0.3f, p);
                }
            }
            p.setStyle(Paint.Style.FILL);
        }

        private void foot(Draw2D c, Person b, int idx) {
            if (b.gibbed[idx]) return;
            Shape s = b.rb[idx].shapes.get(0);
            int shoe = b.kind == Person.SKELETON ? unchecked((int)0xFFe9e5d3U) : (b.kind == Person.ROBOT ? unchecked((int)0xFF5d6670U) : shoeColor(b));
            limb(c, s, hurtColor(b, idx, shoe));
            if (detail && b.kind == Person.HUMAN && b.frozenT <= 0f) {
                // the sole and the laces, in the shoe's own frame
                local(c, s.cx, s.cy, (float) Math.atan2(s.ay, s.ax));
                float ext = s.hl + s.r * 0.75f, up = b.dir * s.ax >= 0f ? 1f : -1f;
                p.setStyle(Paint.Style.STROKE);
                p.setStrokeWidth(s.r * 0.42f); p.setColor(shoe == SHOE[1] ? unchecked((int)0xFFc9302cU) : unchecked((int)0xFFe9e5dcU));
                c.drawLine(-ext, s.r * 0.62f * up, ext, s.r * 0.62f * up, p);
                p.setStrokeWidth(Math.max(0.8f, s.r * 0.16f)); p.setColor(shoe == SHOE[1] ? unchecked((int)0xFF8a929cU) : alpha(unchecked((int)0xFFffffffU), 0.6f));
                float fwd = b.dir * (s.ax >= 0f ? 1f : -1f);
                for (int i = 0; i < 2; i++) { float lx = fwd * (s.hl * 0.05f + i * s.r * 0.5f); c.drawLine(lx, -s.r * 0.75f * up, lx + fwd * s.r * 0.25f, -s.r * 0.35f * up, p); }
                p.setStyle(Paint.Style.FILL);
                c.restore();
            }
            soaked(c, b, idx, s);
            wounds(c, b, idx);
        }

        /** Bullet holes, cuts, burns and bruises in the part's own frame; open wounds drip while they bleed. */
        private void wounds(Draw2D c, Person b, int idx) {
            if (b.nw == 0) return;
            Shape s = b.rb[idx].shapes.get(0);
            bool open = false;
            bool metal = b.kind == Person.ROBOT, bone = b.kind == Person.SKELETON, z = b.kind == Person.ZOMBIE;
            int deep0 = metal ? unchecked((int)0xFF15171bU) : (bone ? unchecked((int)0xFF4a4536U) : (z ? unchecked((int)0xFF2c4a14U) : (gore ? unchecked((int)0xFF4a060bU) : unchecked((int)0xFF2e2e33U))));
            int red0 = metal ? unchecked((int)0xFF3a3f47U) : (bone ? unchecked((int)0xFF8d8774U) : (z ? unchecked((int)0xFF4f8a2aU) : (gore ? unchecked((int)0xFF9a1018U) : unchecked((int)0xFF5d5d66U))));
            int deep = deep0, red = red0;
            bool drips = gore && flesh(b) && b.frozenT <= 0f && detail, dropsOn = drips;
            float dropX = s.ay, dropY = s.ax;                 // world "down" in the shape's frame
            float bleed = Math.min(1f, b.bleed[idx] / 8f + b.soak[idx] * 0.6f);
            for (int i = 0; i < b.nw; i++) {
                if (b.wpart[i] != idx || b.ws[i] <= 0f) continue;
                if (!open) { local(c, s.cx, s.cy, (float) Math.atan2(s.ay, s.ax)); open = true; }
                float u = b.wu[i], v = b.wv[i], r = b.ws[i];
                float age = b.wt[i], clot = Math.min(1f, age / 45f), fresh = Math.max(0f, 1f - age / 4f);
                // gore V6: wounds clot and darken, and a fresh one is wet and glossy
                if (gore && flesh(b)) { red = mix(red0, z ? unchecked((int)0xFF2c4616U) : unchecked((int)0xFF3a0a0cU), clot * 0.8f); deep = mix(deep0, unchecked((int)0xFF1a0305U), clot * 0.6f); }
                if (age > 25f) dropsOn = false; else dropsOn = drips;
                p.setStyle(Paint.Style.FILL);
                switch (b.wkind[i]) {
                    case Person.W_HOLE:
                        if (dropsOn && bleed > 0.05f) {
                            float len = r * (1.5f + 3.5f * bleed);
                            p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(Math.max(1.2f, r * 0.55f)); p.setColor(alpha(red, 0.9f));
                            c.drawLine(u, v, u + dropX * len, v + dropY * len, p);
                            p.setStyle(Paint.Style.FILL); c.drawCircle(u + dropX * len, v + dropY * len, Math.max(0.9f, r * 0.38f), p);
                        }
                        if (gore && flesh(b)) { p.setColor(alpha(unchecked((int)0xFF3a1208U), 0.45f)); c.drawCircle(u, v, r * 1.6f, p); }
                        p.setColor(red); c.drawCircle(u, v, r * 1.25f, p);
                        p.setColor(deep); c.drawCircle(u, v, r * 0.75f, p);
                        if (gore && flesh(b) && fresh > 0f) { p.setColor(alpha(unchecked((int)0xFFffd0d0U), 0.5f * fresh)); c.drawCircle(u - r * 0.3f, v - r * 0.3f, r * 0.25f, p); }
                        if (metal) { p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(1f); p.setColor(unchecked((int)0xFFb5bcc6U)); c.drawCircle(u, v, r * 1.3f, p); }
                        break;
                    case Person.W_CUT: {
                        float dx = (float) Math.cos(b.wa[i]) * r, dy = (float) Math.sin(b.wa[i]) * r;
                        p.setStyle(Paint.Style.STROKE);
                        p.setStrokeWidth(Math.max(2f, r * 0.5f)); p.setColor(red);
                        c.drawLine(u - dx, v - dy, u + dx, v + dy, p);
                        p.setStrokeWidth(Math.max(1f, r * 0.2f)); p.setColor(deep);
                        c.drawLine(u - dx * 0.8f, v - dy * 0.8f, u + dx * 0.8f, v + dy * 0.8f, p);
                        if (gore && flesh(b) && detail) {
                            // the skin curls back at the edges
                            p.setStrokeWidth(Math.max(0.8f, r * 0.12f)); p.setColor(alpha(unchecked((int)0xFFf0c8b0U), 0.55f));
                            c.drawLine(u - dx * 0.9f - dy * 0.3f, v - dy * 0.9f + dx * 0.3f, u + dx * 0.9f - dy * 0.3f, v + dy * 0.9f + dx * 0.3f, p);
                            c.drawLine(u - dx * 0.9f + dy * 0.3f, v - dy * 0.9f - dx * 0.3f, u + dx * 0.9f + dy * 0.3f, v + dy * 0.9f - dx * 0.3f, p);
                            if (fresh > 0f) { p.setColor(alpha(unchecked((int)0xFFffffffU), 0.4f * fresh)); c.drawLine(u - dx * 0.5f, v - dy * 0.5f - 0.8f, u + dx * 0.2f, v + dy * 0.2f - 0.8f, p); }
                        }
                        if (dropsOn && bleed > 0.05f) {
                            p.setStrokeWidth(Math.max(1f, r * 0.25f)); p.setColor(alpha(red, 0.85f));
                            for (int k = -1; k <= 1; k += 2) { float len = r * (0.8f + 2.2f * bleed) * (k < 0 ? 0.7f : 1f); c.drawLine(u + dx * 0.5f * k, v + dy * 0.5f * k, u + dx * 0.5f * k + dropX * len, v + dy * 0.5f * k + dropY * len, p); }
                        }
                        break;
                    }
                    case Person.W_BURN:
                        p.setColor(alpha(unchecked((int)0xFF16120fU), 0.55f)); c.drawCircle(u, v, r, p);
                        p.setColor(alpha(unchecked((int)0xFF2a1e17U), 0.5f)); c.drawCircle(u + r * 0.3f, v - r * 0.2f, r * 0.55f, p);
                        if (gore && flesh(b)) { p.setColor(alpha(unchecked((int)0xFFb0402aU), 0.35f)); c.drawCircle(u - r * 0.2f, v + r * 0.1f, r * 0.35f, p); }
                        break;
                    default:
                        {
                            int bc = age < 15f ? unchecked((int)0xFF5a2a5eU) : (age < 40f ? mix(unchecked((int)0xFF5a2a5eU), unchecked((int)0xFF3a4a7aU), (age - 15f) / 25f) : mix(unchecked((int)0xFF3a4a7aU), unchecked((int)0xFF8a8a3aU), Math.min(1f, (age - 40f) / 40f)));
                            p.setColor(alpha(metal ? unchecked((int)0xFF1b1d22U) : bc, 0.32f)); c.drawCircle(u, v, r, p);
                        }
                        p.setColor(alpha(metal ? unchecked((int)0xFF1b1d22U) : unchecked((int)0xFF7a3a2aU), 0.18f)); c.drawCircle(u + r * 0.2f, v, r * 0.6f, p);
                 break; }
            }
            if (open) c.restore();
            p.setStyle(Paint.Style.FILL);
        }

        private void hand(Draw2D c, Person b, int idx) {
            if (b.gibbed[idx]) return;
            RB r = b.rb[idx];
            float hl = r.shapes.get(0).hl, rad = r.shapes.get(0).r;
            float hx = r.localToWorldX(0, hl), hy = r.localToWorldY(0, hl);
            float ux = -(float) Math.sin(r.a), uy = (float) Math.cos(r.a);       // elbow -> wrist
            float nx = -uy, ny = ux, sc = b.scale;
            p.setStyle(Paint.Style.FILL);
            int skin = bodyColor(b, b.skin);
            if (b.kind == Person.RUSTMAN) {
                // claws: three long curved blades, rusty at the base and steel at the tip
                for (int k = -1; k <= 1; k++) {
                    float bx = hx + nx * k * rad * 0.7f, by = hy + ny * k * rad * 0.7f;
                    float len = (24f - Math.abs(k) * 4f) * sc;
                    float tx = bx + ux * len + nx * k * 3f * sc, ty = by + uy * len + ny * k * 3f * sc;
                    poly[0] = bx + nx * 2.2f * sc; poly[1] = by + ny * 2.2f * sc;
                    poly[2] = tx; poly[3] = ty;
                    poly[4] = bx - nx * 2.2f * sc; poly[5] = by - ny * 2.2f * sc;
                    p.setColor(unchecked((int)0xFF2a2018U)); c.drawPoly(poly, 3, p);
                    poly[0] = bx + nx * 1.3f * sc; poly[1] = by + ny * 1.3f * sc;
                    poly[2] = tx - ux * 1.5f; poly[3] = ty - uy * 1.5f;
                    poly[4] = bx - nx * 1.3f * sc; poly[5] = by - ny * 1.3f * sc;
                    p.setColor(k == 0 ? unchecked((int)0xFFd9d3c4U) : unchecked((int)0xFFb9b19cU)); c.drawPoly(poly, 3, p);
                    p.setColor(alpha(unchecked((int)0xFFb5651dU), 0.7f));
                    poly[0] = bx + nx * 1.3f * sc; poly[1] = by + ny * 1.3f * sc;
                    poly[2] = bx + ux * len * 0.4f; poly[3] = by + uy * len * 0.4f;
                    poly[4] = bx - nx * 1.3f * sc; poly[5] = by - ny * 1.3f * sc;
                    c.drawPoly(poly, 3, p);
                }
            } else if (detail && b.kind != Person.ROBOT && b.kind != Person.SKELETON) {
                // fingers fan out a little, and the thumb sticks out on the front side
                p.setStyle(Paint.Style.STROKE);
                p.setStrokeWidth(Math.max(1.4f, rad * 0.55f));
                p.setColor(dark(skin, 0.55f));
                for (int k = -1; k <= 1; k++) c.drawLine(hx, hy, hx + ux * rad * 1.5f + nx * k * rad * 0.45f, hy + uy * rad * 1.5f + ny * k * rad * 0.45f, p);
                p.setStrokeWidth(Math.max(1f, rad * 0.38f));
                p.setColor(skin);
                for (int k = -1; k <= 1; k++) c.drawLine(hx, hy, hx + ux * rad * 1.5f + nx * k * rad * 0.45f, hy + uy * rad * 1.5f + ny * k * rad * 0.45f, p);
                float side = b.dir * (r.shapes.get(0).ax >= 0f ? 1f : 1f);
                p.setStrokeWidth(Math.max(1.2f, rad * 0.45f)); p.setColor(skin);
                c.drawLine(hx, hy, hx + ux * rad * 0.7f + nx * side * rad * 1.15f, hy + uy * rad * 0.7f + ny * side * rad * 1.15f, p);
                p.setStyle(Paint.Style.FILL);
            }
            p.setColor(dark(skin, 0.5f));
            c.drawCircle(hx, hy, rad * 1.15f + 0.9f, p);
            p.setColor(skin);
            c.drawCircle(hx, hy, rad * 1.15f, p);
            if (detail && b.kind != Person.ROBOT && b.kind != Person.SKELETON) {
                float tx = r.localToWorldX(b.dir * rad * 0.7f, hl - rad * 0.2f), ty = r.localToWorldY(b.dir * rad * 0.7f, hl - rad * 0.2f);
                p.setColor(dark(skin, 0.12f)); c.drawCircle(tx, ty, rad * 0.45f, p);
            }
        }

        /** Trousers V2: jeans seams and pockets, chino creases, cargo pockets, shorts cuffs. */
        private void legDetail(Draw2D c, Person b, int idx) {
            int st = bottomStyle(b);
            if (st < 0 || b.gibbed[idx] || !detail || b.frozenT > 0f) return;
            RB rb = b.rb[idx];
            Shape s = rb.shapes.get(0);
            float hl = s.hl, r = s.r;
            int d = b.dir;
            local(c, s.cx, s.cy, (float) Math.atan2(s.ay, s.ax));
            // along +x of this frame is down the leg (hip -> knee)
            int col = bodyColor(b, b.pants);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeCap(Paint.Cap.BUTT);
            float back = -d * r * 0.55f;
            if (st == BOT_JEANS) {
                p.setStrokeWidth(1.1f); p.setColor(alpha(unchecked((int)0xFFd9b46aU), 0.55f));
                c.drawLine(-hl, back, hl + r * 0.6f, back, p);
                if (idx == Person.THIGH_F) { rf.set(-hl - r * 0.3f, d * r * 0.05f - r * 0.4f, -hl + r * 0.9f, d * r * 0.05f + r * 0.4f); c.drawArc(rf, d > 0 ? 270f : 0f, 90f, false, p); }
                p.setColor(alpha(dark(col, 0.35f), 0.7f)); p.setStrokeWidth(1.4f);
                c.drawLine(-hl * 0.3f, back + d * 1.5f, hl * 0.5f, back + d * 1.2f, p);
            } else if (st == BOT_CHINOS) {
                p.setStrokeWidth(1.2f); p.setColor(alpha(light(col, 0.25f), 0.7f));
                c.drawLine(-hl, d * r * 0.25f, hl + r * 0.7f, d * r * 0.25f, p);
            } else if (st == BOT_CARGO) {
                p.setStyle(Paint.Style.FILL);
                p.setColor(dark(col, 0.25f)); rf.set(-hl * 0.15f, -r * 0.55f, hl * 0.6f, r * 0.45f); c.drawRoundRect(rf, 2f, 2f, p);
                p.setColor(dark(col, 0.12f)); rf.set(-hl * 0.15f, -r * 0.55f, hl * 0.05f, r * 0.45f); c.drawRect(rf, p);
                p.setColor(unchecked((int)0xFF2b2b30U)); c.drawCircle(-hl * 0.05f, -r * 0.05f, 1f, p);
            } else if (st == BOT_SHORTS) {
                p.setStyle(Paint.Style.FILL);
                p.setColor(dark(col, 0.22f)); rf.set(hl + r * 0.3f, -r * 1.02f, hl + r * 0.95f, r * 1.02f); c.drawRect(rf, p);
            }
            p.setStrokeCap(Paint.Cap.ROUND);
            p.setStyle(Paint.Style.FILL);
            c.restore();
        }

        /** Gore V5: a chest torn open shows the ribs, the lungs and a beating heart with its vessels. */
        private void ribcage(Draw2D c, Person b) {
            if (!gore || !flesh(b) || b.gibbed[Person.CHEST] || !detail || b.frozenT > 0f) return;
            float dmg = -b.hp[Person.CHEST] / Person.maxHp(b, Person.CHEST);
            if (dmg < 0.4f) return;
            float k = Math.min(1f, (dmg - 0.4f) * 2.2f), s = b.scale;
            bool z = b.kind == Person.ZOMBIE;
            RB ch = b.rb[Person.CHEST];
            int d = b.dir;
            float hl = 22f * s, hw = 11.5f * s;
            local(c, ch.x, ch.y, ch.a);
            p.setStyle(Paint.Style.FILL);
            // the open cavity: dark red, fading in
            p.setColor(alpha(z ? unchecked((int)0xFF22350fU) : unchecked((int)0xFF3a0509U), 0.55f + 0.4f * k));
            rf.set(-hw * 0.85f, -hl * 0.8f, hw * 0.85f, hl * 0.45f); c.drawRoundRect(rf, hw * 0.4f, hw * 0.4f, p);
            // lungs
            p.setColor(z ? unchecked((int)0xFF7f9a58U) : unchecked((int)0xFFd98a98U));
            rf.set(-hw * 0.78f, -hl * 0.72f, -hw * 0.05f, hl * 0.2f); c.drawOval(rf, p);
            rf.set(hw * 0.05f, -hl * 0.72f, hw * 0.78f, hl * 0.2f); c.drawOval(rf, p);
            p.setColor(alpha(unchecked((int)0xFFffffffU), 0.2f));
            rf.set(-hw * 0.6f, -hl * 0.65f, -hw * 0.35f, -hl * 0.25f); c.drawOval(rf, p);
            rf.set(hw * 0.25f, -hl * 0.65f, hw * 0.5f, -hl * 0.25f); c.drawOval(rf, p);
            // the windpipe and the big vessels
            p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(2.2f * s); p.setColor(unchecked((int)0xFFe9d9c4U));
            c.drawLine(0, -hl * 0.95f, 0, -hl * 0.4f, p);
            p.setStrokeWidth(1.6f * s); p.setColor(z ? unchecked((int)0xFF4a6a22U) : unchecked((int)0xFF8e0f1cU));
            c.drawLine(d * hw * 0.1f, -hl * 0.45f, d * hw * 0.05f, -hl * 0.78f, p);
            p.setColor(z ? unchecked((int)0xFF55713aU) : unchecked((int)0xFF3a5a9aU));
            c.drawLine(-d * hw * 0.1f, -hl * 0.4f, -d * hw * 0.12f, -hl * 0.75f, p);
            // the heart, beating while they live
            float pulse = b.dead ? 1f : 1f + 0.16f * Math.max(0f, (float) Math.sin(time * 9f + b.id));
            float hx = d * hw * 0.12f, hy = -hl * 0.12f, hr = hw * 0.3f * pulse;
            p.setStyle(Paint.Style.FILL);
            p.setColor(z ? unchecked((int)0xFF4a6a22U) : unchecked((int)0xFF7a0f1aU)); c.drawCircle(hx, hy, hr + 1.2f * s, p);
            p.setColor(z ? unchecked((int)0xFF6f9038U) : unchecked((int)0xFFc2202fU)); c.drawCircle(hx, hy, hr, p);
            poly[0] = hx - hr * 0.9f; poly[1] = hy + hr * 0.4f; poly[2] = hx + hr * 0.9f; poly[3] = hy + hr * 0.4f; poly[4] = hx; poly[5] = hy + hr * 1.5f;
            c.drawPoly(poly, 3, p);
            p.setColor(alpha(unchecked((int)0xFFffffffU), 0.3f)); c.drawCircle(hx - hr * 0.35f, hy - hr * 0.35f, hr * 0.28f, p);
            // ribs curving over everything, and the breastbone
            p.setStyle(Paint.Style.STROKE); p.setStrokeCap(Paint.Cap.BUTT);
            for (int i = 0; i < 4; i++) {
