                float x = s.cx + s.ax * s.hl * t - s.ay * off * s.r * 0.6f, y = s.cy + s.ay * s.hl * t + s.ax * off * s.r * 0.6f;
                p.setColor(alpha(i % 2 == 0 ? unchecked((int)0xFF8a3a10U) : unchecked((int)0xFFc9772aU), 0.55f + 0.3f * k));
