                    p.setColor(hairStyle(b) == 3 ? dark(col, 0.4f) : dark(bodyColor(b, b.hair), 0.15f));
                    float inner = scared ? -r * 0.06f : (b.kind == Person.THUG || z ? r * 0.08f : 0f);
                    c.drawLine(ex - d * r * 0.22f, ey - r * 0.3f, ex + d * r * 0.2f, ey - r * 0.3f + inner, p);
                    // mouth: neutral, open in pain or fear, or a zombie's sneer
                    p.setStrokeWidth(1.6f);
                    if (rm) {
                        // a jagged mouth full of broken teeth
                        p.setStyle(Paint.Style.FILL); p.setColor(unchecked((int)0xFF2a0a04U));
                        rf.set(d > 0 ? r * 0.2f : -r * 0.85f, r * 0.34f, d > 0 ? r * 0.85f : -r * 0.2f, r * 0.68f); c.drawRect(rf, p);
                        p.setColor(unchecked((int)0xFFe0d8b8U));
                        for (int i = 0; i < 4; i++) { float tx = (d > 0 ? r * 0.25f : -r * 0.8f) + i * r * 0.15f; poly[0] = tx; poly[1] = r * 0.34f; poly[2] = tx + r * 0.1f; poly[3] = r * 0.34f; poly[4] = tx + r * 0.05f; poly[5] = r * 0.5f; c.drawPoly(poly, 3, p); }
                        p.setStyle(Paint.Style.STROKE);
                    }
                    else if (z) { p.setColor(unchecked((int)0xFF4a1010U)); c.drawLine(d * r * 0.25f, r * 0.45f, d * r * 0.75f, r * 0.55f, p); }
                    else if (scared) {
                        p.setStyle(Paint.Style.FILL); p.setColor(unchecked((int)0xFF3a0a0eU));
                        rf.set(d * r * 0.55f - r * 0.17f, r * 0.34f, d * r * 0.55f + r * 0.17f, r * 0.7f); c.drawOval(rf, p);
                    } else { p.setColor(unchecked((int)0xFF1b1b1bU)); c.drawLine(d * r * 0.3f, r * 0.42f, d * r * 0.72f, r * 0.42f, p); }
                }
                p.setStyle(Paint.Style.FILL);
                // gore V4: a skull cracked by the blows, and the brain showing when it caves in
                if (gore && dmg > 0.45f && b.frozenT <= 0f) {
                    p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(1.4f); p.setColor(z ? unchecked((int)0xFF2f4a14U) : unchecked((int)0xFF5e0a10U));
                    c.drawLine(-d * r * 0.7f, -r * 0.85f, -d * r * 0.25f, -r * 0.4f, p);
                    c.drawLine(-d * r * 0.25f, -r * 0.4f, -d * r * 0.05f, -r * 0.65f, p);
                    c.drawLine(-d * r * 0.25f, -r * 0.4f, -d * r * 0.45f, -r * 0.05f, p);
                    p.setStyle(Paint.Style.FILL);
                    if (dmg > 0.8f) {
                        p.setColor(unchecked((int)0xFFefe9d6U)); c.drawCircle(-d * r * 0.35f, -r * 0.62f, r * 0.48f, p);
                        p.setColor(z ? unchecked((int)0xFF8aa86aU) : unchecked((int)0xFFe39aa8U)); c.drawCircle(-d * r * 0.35f, -r * 0.62f, r * 0.38f, p);
                        p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(1f); p.setColor(z ? unchecked((int)0xFF55703aU) : unchecked((int)0xFFb25a6aU));
                        rf.set(-d * r * 0.35f - r * 0.25f, -r * 0.85f, -d * r * 0.35f + r * 0.05f, -r * 0.55f); c.drawArc(rf, 0f, 200f, false, p);
                        rf.set(-d * r * 0.35f - r * 0.05f, -r * 0.75f, -d * r * 0.35f + r * 0.25f, -r * 0.45f); c.drawArc(rf, 180f, 200f, false, p);
                        p.setStyle(Paint.Style.FILL);
                        p.setColor(alpha(unchecked((int)0xFF8e1111U), 0.6f)); c.drawCircle(-d * r * 0.1f, -r * 0.3f, r * 0.12f, p);
                    }
                }
                // gore V6: a ruined chest or head fills the mouth with blood that runs down the chin
                if (gore && !z && !rm && !b.gibbed[Person.CHEST] && (b.hp[Person.CHEST] < -15f || dmg > 0.4f || b.soak[Person.HEAD] > 0.5f)) {
                    p.setStyle(Paint.Style.FILL); p.setColor(alpha(unchecked((int)0xFF7a0a10U), 0.9f));
                    rf.set(d > 0 ? r * 0.28f : -r * 0.78f, r * 0.4f, d > 0 ? r * 0.78f : -r * 0.28f, r * 0.56f); c.drawRoundRect(rf, 2f, 2f, p);
                    p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(Math.max(1.2f, r * 0.12f)); p.setColor(alpha(unchecked((int)0xFF8e0f18U), 0.9f));
                    c.drawLine(d * r * 0.55f, r * 0.55f, d * r * 0.5f, r * (0.95f + 0.2f * (float) Math.sin(time * 2f + b.id)), p);
                    p.setStyle(Paint.Style.FILL);
                }
                // gore V5: with the skull crushed an eye pops out and dangles on its nerve
                if (gore && dmg > 0.85f && !z && b.frozenT <= 0f) {
                    float ex2 = d * r * 0.5f, ey2 = -r * 0.12f;
                    float sway = (float) Math.sin(time * 3f + b.id) * r * 0.08f;
                    float bx2 = ex2 + d * r * 0.25f + sway, by2 = ey2 + r * 0.85f;
                    p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(Math.max(1f, r * 0.1f)); p.setColor(unchecked((int)0xFFa5202cU));
                    c.drawLine(ex2, ey2, bx2, by2 - r * 0.15f, p);
                    p.setStyle(Paint.Style.FILL);
                    p.setColor(unchecked((int)0xFF5a0a10U)); c.drawCircle(ex2, ey2, r * 0.22f, p);
                    p.setColor(unchecked((int)0xFFf4f4eeU)); c.drawCircle(bx2, by2, r * 0.26f, p);
                    p.setColor(unchecked((int)0xFF1b1b1bU)); c.drawCircle(bx2 + d * r * 0.05f, by2 + r * 0.04f, r * 0.11f, p);
                    p.setColor(alpha(unchecked((int)0xFFffffffU), 0.6f)); c.drawCircle(bx2 - r * 0.08f, by2 - r * 0.08f, r * 0.05f, p);
                }
                hat(c, b, r);
            }
            c.restore();
        }

        private void hat(Draw2D c, Person b, float r) {
            p.setStyle(Paint.Style.FILL);
            int d = b.dir;
            switch (b.kind) {
                case Person.SOLDIER:
                    p.setColor(bodyColor(b, unchecked((int)0xFF3f4a2cU)));
                    rf.set(-r * 1.12f, -r * 1.2f, r * 1.12f, r * 0.9f); c.drawArc(rf, 180f, 180f, true, p);
                    rf.set(-r * 1.25f, -r * 0.22f, r * 1.25f, r * 0.02f); c.drawRoundRect(rf, r * 0.1f, r * 0.1f, p);
                    break;
                case Person.MEDIC:
                    p.setColor(bodyColor(b, unchecked((int)0xFFf4f6f8U)));
                    rf.set(-r * 0.98f, -r * 1.05f, r * 0.98f, r * 0.55f); c.drawArc(rf, 180f, 180f, true, p);
                    p.setColor(unchecked((int)0xFFe0332cU));
                    rf.set(-r * 0.08f, -r * 0.92f, r * 0.08f, -r * 0.4f); c.drawRect(rf, p);
                    rf.set(-r * 0.26f, -r * 0.74f, r * 0.26f, -r * 0.58f); c.drawRect(rf, p);
                    break;
                case Person.FIREFIGHTER:
                    p.setColor(bodyColor(b, unchecked((int)0xFFf2b134U)));
                    rf.set(-r * 1.1f, -r * 1.25f, r * 1.1f, r * 0.85f); c.drawArc(rf, 180f, 180f, true, p);
                    rf.set(-d * r * 0.6f - r * 0.75f, -r * 0.24f, -d * r * 0.6f + r * 0.75f, r * 0.04f); c.drawRoundRect(rf, r * 0.12f, r * 0.12f, p);
                    p.setColor(unchecked((int)0xFFd5d9deU)); c.drawCircle(d * r * 0.55f, -r * 0.55f, r * 0.2f, p);
                    break;
                case Person.THUG:
                    p.setColor(bodyColor(b, unchecked((int)0xFF1c1e22U)));
                    rf.set(-r * 1.02f, -r * 1.12f, r * 1.02f, r * 0.6f); c.drawArc(rf, 180f, 180f, true, p);
                    if (!b.dead) {
                        p.setColor(unchecked((int)0xFF0d0e10U));
                        float xa = d * r * 0.15f, xb = d * r * 0.95f;
                        rf.set(Math.min(xa, xb), -r * 0.3f, Math.max(xa, xb), r * 0.05f); c.drawRoundRect(rf, r * 0.1f, r * 0.1f, p);
                    }
                    break;
                default: break;
            }
        }

        private void gear(Draw2D c, Person b) {
            if (b.kind != Person.SOLDIER && b.kind != Person.FIREFIGHTER) return;
            if (b.severed[Person.SH_F] || b.severed[Person.EL_F] || b.gibbed[Person.FARM_F] || b.gibbed[Person.CHEST]) return;
            float s = b.scale;
            RB f = b.rb[Person.FARM_F];
            float hl = f.shapes.get(0).hl;
            float hx = f.localToWorldX(0, hl), hy = f.localToWorldY(0, hl);
            float ux = -(float) Math.sin(f.a), uy = (float) Math.cos(f.a);        // elbow -> wrist
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeCap(Paint.Cap.ROUND);
            if (b.kind == Person.SOLDIER) {
                // the same rifle model as the loose one, gripped at the hand
                c.save();
                c.translate(hx, hy);
                c.rotate((float) Math.toDegrees(Math.atan2(uy, ux)));
                if (ux < 0) c.scale(1f, -1f);
                c.scale(s * 0.85f, s * 0.85f);
                c.translate(11f, -8f);
                drawGun(c, 1, 25f, false, b.dead ? 0 : 1);
                c.restore();
                p.setStyle(Paint.Style.STROKE);
            } else {
                RB ch = b.rb[Person.CHEST];
                float tx = ch.localToWorldX(-b.dir * 13f * s, 6f * s), ty = ch.localToWorldY(-b.dir * 13f * s, 6f * s);
                p.setColor(bodyColor(b, unchecked((int)0xFFc93a2cU))); p.setStrokeWidth(10f * s);
                c.drawLine(tx, ty - 10f * s, tx, ty + 14f * s, p);
                p.setColor(unchecked((int)0xFF1d1f24U)); p.setStrokeWidth(2.6f * s);
                float mx = (tx + hx) * 0.5f, my = Math.max(ty, hy) + 14f * s;
                c.drawLine(tx, ty + 14f * s, mx, my, p);
                c.drawLine(mx, my, hx, hy, p);
                p.setColor(unchecked((int)0xFFb9c0caU)); p.setStrokeWidth(4f * s);
                c.drawLine(hx, hy, hx + ux * 12f * s, hy + uy * 12f * s, p);
            }
            p.setStyle(Paint.Style.FILL);
        }

        private void inspectOverlay(Draw2D c, Person b) {
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeCap(Paint.Cap.ROUND);
            for (int i = 0; i < Person.NPARTS; i++) {
                if (i == Person.HEAD || b.gibbed[i]) continue;
                Shape s = b.rb[i].shapes.get(0);
                float h = Math.max(0f, Math.min(1f, b.hp[i] / Person.maxHp(b, i)));
                int col = b.broken[i] ? unchecked((int)0xFFc061ffU) : (h > 0.5f ? mix(unchecked((int)0xFFf2d13aU), unchecked((int)0xFF4cdc6bU), (h - 0.5f) * 2f) : mix(unchecked((int)0xFFe0463cU), unchecked((int)0xFFf2d13aU), h * 2f));
                p.setColor(alpha(col, 0.6f));
                p.setStrokeWidth(s.r * 2f + 2f);
                c.drawLine(s.cx - s.ax * s.hl, s.cy - s.ay * s.hl, s.cx + s.ax * s.hl, s.cy + s.ay * s.hl, p);
            }
            RB hd = b.rb[Person.HEAD];
            float hh = Math.max(0f, b.hp[Person.HEAD] / Person.maxHp(b, Person.HEAD));
            p.setStyle(Paint.Style.FILL);
            p.setColor(alpha(hh > 0.5f ? unchecked((int)0xFF4cdc6bU) : unchecked((int)0xFFe0463cU), 0.45f));
            c.drawCircle(hd.x, hd.y, hd.shapes.get(0).r, p);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(2.5f);
            p.setColor(unchecked((int)0xCCffffffU));
            c.drawCircle(b.cx(), b.cy() - 40f * b.scale, b.radius() * 0.8f, p);
            p.setStyle(Paint.Style.FILL);
        }
    }
